// correctionC is where relationship counts are stored.
type correctionC struct {
	CorrectionMemberBurdens *int64
	CorrectionPayments      *int64
}

// PreloadCount sets a count in the C struct by name
func (o *Correction) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "CorrectionMemberBurdens":
		o.C.CorrectionMemberBurdens = &count
	case "CorrectionPayments":
		o.C.CorrectionPayments = &count
	}
	return nil
}

type correctionCountPreloader struct {
	CorrectionMemberBurdens func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	CorrectionPayments      func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
}

func buildCorrectionCountPreloader() correctionCountPreloader {
	return correctionCountPreloader{
		CorrectionMemberBurdens: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Correction]("CorrectionMemberBurdens", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Corrections.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(CorrectionMemberBurdens.NameAsExpr()),
					sm.Where(psql.Quote(CorrectionMemberBurdens.Alias(), "household_id").EQ(psql.Quote(parent, "household_id"))),
					sm.Where(psql.Quote(CorrectionMemberBurdens.Alias(), "correction_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		CorrectionPayments: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Correction]("CorrectionPayments", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Corrections.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(CorrectionPayments.NameAsExpr()),
					sm.Where(psql.Quote(CorrectionPayments.Alias(), "correction_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
	}
}

type correctionCountThenLoader[Q orm.Loadable] struct {
	CorrectionMemberBurdens func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	CorrectionPayments      func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildCorrectionCountThenLoader[Q orm.Loadable]() correctionCountThenLoader[Q] {
	type CorrectionMemberBurdensCountInterface interface {
		LoadCountCorrectionMemberBurdens(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type CorrectionPaymentsCountInterface interface {
		LoadCountCorrectionPayments(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return correctionCountThenLoader[Q]{
		CorrectionMemberBurdens: countThenLoadBuilder[Q](
			"CorrectionMemberBurdens",
			func(ctx context.Context, exec bob.Executor, retrieved CorrectionMemberBurdensCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountCorrectionMemberBurdens(ctx, exec, mods...)
			},
		),
		CorrectionPayments: countThenLoadBuilder[Q](
			"CorrectionPayments",
			func(ctx context.Context, exec bob.Executor, retrieved CorrectionPaymentsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountCorrectionPayments(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountCorrectionMemberBurdens loads the count of CorrectionMemberBurdens into the C struct
func (o *Correction) LoadCountCorrectionMemberBurdens(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.CorrectionMemberBurdens(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.CorrectionMemberBurdens = &count
	return nil
}

// LoadCountCorrectionMemberBurdens loads the count of CorrectionMemberBurdens for a slice in a single batch query
func (os CorrectionSlice) LoadCountCorrectionMemberBurdens(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkHouseholdID := make(pgtypes.Array[uuid.UUID], 0, len(os))
	pkID := make(pgtypes.Array[uuid.UUID], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkHouseholdID = append(pkHouseholdID, o.HouseholdID)
		pkID = append(pkID, o.ID)
	}

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		HouseholdID uuid.UUID

		ID    uuid.UUID
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			CorrectionMemberBurdens.Columns.HouseholdID.As("household_id"),
			CorrectionMemberBurdens.Columns.CorrectionID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(CorrectionMemberBurdens.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.InnerJoin(psql.Select(
			sm.Distinct(),
			sm.Columns(
				psql.Quote("bob_rel_keys_src", "HouseholdID"),
				psql.Quote("bob_rel_keys_src", "CorrectionID"),
			),
			sm.From(psql.F("unnest",
				psql.Cast(psql.Arg(pkHouseholdID), "uuid[]"),
				psql.Cast(psql.Arg(pkID), "uuid[]"),
			)).As("bob_rel_keys_src", "HouseholdID", "CorrectionID"),
		)).As("bob_rel_keys").On(
			CorrectionMemberBurdens.Columns.HouseholdID.EQ(psql.Quote("bob_rel_keys", "HouseholdID")),
			CorrectionMemberBurdens.Columns.CorrectionID.EQ(psql.Quote("bob_rel_keys", "CorrectionID")),
		),
		// GROUP BY fk columns
		sm.GroupBy(CorrectionMemberBurdens.Columns.HouseholdID),
		sm.GroupBy(CorrectionMemberBurdens.Columns.CorrectionID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Composite FK: use a key struct
	type countKey struct {
		HouseholdID uuid.UUID

		ID uuid.UUID
	}
	countMap := make(map[countKey]int64, len(results))
	for _, r := range results {
		countMap[countKey{
			HouseholdID: r.HouseholdID,

			ID: r.ID,
		}] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[countKey{
			HouseholdID: o.HouseholdID,

			ID: o.ID,
		}]
		o.C.CorrectionMemberBurdens = &count
	}

	return nil
}

// LoadCountCorrectionPayments loads the count of CorrectionPayments into the C struct
func (o *Correction) LoadCountCorrectionPayments(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.CorrectionPayments(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.CorrectionPayments = &count
	return nil
}

// LoadCountCorrectionPayments loads the count of CorrectionPayments for a slice in a single batch query
func (os CorrectionSlice) LoadCountCorrectionPayments(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkID := make(pgtypes.Array[uuid.UUID], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkID = append(pkID, o.ID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkID), "uuid[]"))

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    uuid.UUID
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			CorrectionPayments.Columns.CorrectionID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(CorrectionPayments.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(CorrectionPayments.Columns.CorrectionID.EQ(PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(CorrectionPayments.Columns.CorrectionID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[uuid.UUID]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.CorrectionPayments = &count
	}

	return nil
}

type correctionJoins[Q dialect.Joinable] struct {
	typ                     string
	CorrectionMemberBurdens modAs[Q, correctionMemberBurdenColumns]
	CorrectionPayments      modAs[Q, correctionPaymentColumns]
	CreatedByMember         modAs[Q, memberColumns]
	AccountingPeriod        modAs[Q, accountingPeriodColumns]
	Household               modAs[Q, householdColumns]
	Purchase                modAs[Q, purchaseColumns]
	Journal                 modAs[Q, journalColumns]
	PurchaseItem            modAs[Q, purchaseItemColumns]
}

func (j correctionJoins[Q]) aliasedAs(alias string) correctionJoins[Q] {
	return buildCorrectionJoins[Q](buildCorrectionColumns(alias), j.typ)
}

func buildCorrectionJoins[Q dialect.Joinable](cols correctionColumns, typ string) correctionJoins[Q] {
	return correctionJoins[Q]{
		typ: typ,
		CorrectionMemberBurdens: modAs[Q, correctionMemberBurdenColumns]{
			c: CorrectionMemberBurdens.Columns,
			f: func(to correctionMemberBurdenColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, CorrectionMemberBurdens.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.CorrectionID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		CorrectionPayments: modAs[Q, correctionPaymentColumns]{
			c: CorrectionPayments.Columns,
			f: func(to correctionPaymentColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, CorrectionPayments.NameExpr().As(to.Alias())).On(
						to.CorrectionID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		CreatedByMember: modAs[Q, memberColumns]{
			c: Members.Columns,
			f: func(to memberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Members.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.CreatedBy),
					))
				}

				return mods
			},
		},
		AccountingPeriod: modAs[Q, accountingPeriodColumns]{
			c: AccountingPeriods.Columns,
			f: func(to accountingPeriodColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, AccountingPeriods.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.Period.EQ(cols.EffectivePeriod),
					))
				}

				return mods
			},
		},
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
		Purchase: modAs[Q, purchaseColumns]{
			c: Purchases.Columns,
			f: func(to purchaseColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Purchases.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.PurchaseID),
					))
				}

				return mods
			},
		},
		Journal: modAs[Q, journalColumns]{
			c: Journals.Columns,
			f: func(to journalColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Journals.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.JournalID),
					))
				}

				return mods
			},
		},
		PurchaseItem: modAs[Q, purchaseItemColumns]{
			c: PurchaseItems.Columns,
			f: func(to purchaseItemColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, PurchaseItems.NameExpr().As(to.Alias())).On(
						to.PurchaseID.EQ(cols.PurchaseID), to.ID.EQ(cols.ItemID),
					))
				}

				return mods
			},
		},
	}
}
